declarations:
VAR_EXTERNAL
    G_Ready : BOOL;
    G_State : INT;
END_VAR

body:
(* Startup task only: application state, no hardware commands. *)
G_Ready := FALSE;
G_State := INT#0;

declarations:
VAR
    xRequest : BOOL := FALSE;
    xLast : BOOL := FALSE;
    xInitialized : BOOL := FALSE;
    xPulse : BOOL := FALSE;
END_VAR

body:
xPulse := FALSE;
IF NOT xInitialized THEN
    xLast := xRequest;
    xInitialized := TRUE;
ELSE
    xPulse := xRequest AND NOT xLast;
    xLast := xRequest;
END_IF;

declarations:
VAR
    Request : BOOL := FALSE;
    AckA : BOOL := FALSE;
    AckB : BOOL := FALSE;
    OperationError : BOOL := FALSE;
    ResetRequest : BOOL := FALSE;
    StartA : BOOL := FALSE;
    StartB : BOOL := FALSE;
    Complete : BOOL := FALSE;
    Fault : BOOL := FALSE;
    State : INT := INT#0;
END_VAR

body:
StartA := FALSE;
StartB := FALSE;
Complete := FALSE;
CASE State OF
    0:
        IF Request AND NOT Fault THEN State := INT#10; END_IF;
    10:
        StartA := TRUE;
        IF OperationError THEN State := INT#900;
        ELSIF AckA THEN State := INT#20; END_IF;
    20:
        StartB := TRUE;
        IF OperationError THEN State := INT#900;
        ELSIF AckB THEN State := INT#30; END_IF;
    30:
        Complete := TRUE;
        IF NOT Request THEN State := INT#0; END_IF;
    900:
        Fault := TRUE;
        IF ResetRequest AND NOT Request AND NOT OperationError THEN
            Fault := FALSE;
            State := INT#0;
        END_IF;
ELSE
    Fault := TRUE;
    State := INT#900;
END_CASE;

declarations:
VAR_EXTERNAL
    Axis : AXIS_REF;
END_VAR
VAR
    fbPosition : MC_ReadActualPosition;
    MonitorEnable : BOOL := FALSE;
    PositionValid : BOOL := FALSE;
    LastPosition : LREAL := LREAL#0.0;
    ReadFault : BOOL := FALSE;
    LastErrorID : UINT := UINT#0;
END_VAR

body:
fbPosition(Axis := Axis, Enable := MonitorEnable);
PositionValid := fbPosition.Valid;
IF PositionValid THEN
    LastPosition := fbPosition.Position;
END_IF;
IF fbPosition.Error THEN
    ReadFault := TRUE;
    LastErrorID := fbPosition.ErrorID;
END_IF;
